mapper.select:
SELECT cd.company_document_id AS companyDocumentId, lv.company_document_version_id AS companyDocumentVersionId, cd.category AS category, lv.original_file_name AS originalFileName, lv.version_no AS versionNo, NULL AS indexStatus FROM company_document cd JOIN ( SELECT v.company_document_id, MAX(v.version_no) AS mx FROM company_document_version v JOIN company_document cdj ON cdj.company_document_id = v.company_document_id AND cdj.company_id = #{companyId} WHERE v.upload_status = 'COMPLETED' AND v.deleted_at IS NULL GROUP BY v.company_document_id ) vc ON vc.company_document_id = cd.company_document_id JOIN company_document_version lv ON lv.company_document_id = cd.company_document_id AND lv.version_no = vc.mx AND lv.upload_status = 'COMPLETED' AND lv.deleted_at IS NULL WHERE cd.company_id = #{companyId} AND cd.deleted_at IS NULL AND cd.category = #{category}
AND (cd.name LIKE CONCAT('%', #{keyword}, '%') OR lv.original_file_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY lv.completed_at DESC, cd.company_document_id DESC
